# Human-prose typography only; identifiers, URLs and numeric comma groups are never changed.
import re
fix={'vision2047':'vision 2047','Nobel2026':'Nobel 2026','Mission2.0':'Mission 2.0','at21':'at 21','from constitutional':'from constitutional','distinguish1926from':'distinguish 1926 from','5.56kmfree':'5.56 km free','QNuLabs':'QNu Labs','Visakhapatnamorother':'Visakhapatnam or other','CycloneMurasucompletion':'Cyclone Murasu completion','3Rs':'3Rs','Section4':'Section 4','Article19':'Article 19','Section69':'Section 69','0.5%':'0.5%'}
protect=['CO2','3Rs','P2P','P2M','P2PM','C2','FY2026','FY2027','FY2039','2.0']
def clean(s):
 for a,b in fix.items():s=s.replace(a,b)
 for i,x in enumerate(protect):s=s.replace(x,'§'+chr(65+i)+'§')
 s=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',s);s=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',s)
 s=re.sub(r'(?<=[,;:])(?=[A-Za-z₹])',' ',s)
 s=re.sub(r'(?<=%)(?=[A-Za-z])',' ',s)
 for i,x in enumerate(protect):s=s.replace('§'+chr(65+i)+'§',x)
 for a,b in {'°Cby':'°C by','°Cunder':'°C under','°Cfor':'°C for','kmfree':'km free','km/h':'km/h','risk-free':'risk-free','2026 in':'2026 in','Centreof':'Centre of'}.items():s=s.replace(a,b)
 return re.sub(' +',' ',s).strip()
for n in J:
 for k in ['title','why','static_link','trap','mains']:n[k]=clean(n[k])
 for k in ['facts','analysis']:n[k]=[clean(x)for x in n[k]]
N.extend(J)
